INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('9d1f471d-538f-508e-be77-c53faffa0d70','07ab185c-b5c3-5945-bd19-7faa92a2fa80','The verb ''have got''',0,'LESSON',70,$j$[{"type": "rule", "text": "Use 'have got' with I, you, we, they. Use 'has got' with he, she, it."}, {"type": "rule", "text": "Negative: haven't got / hasn't got."}, {"type": "rule", "text": "Questions: Have you got ...? Has she got ...? Short answers: Yes, I have. / No, she hasn't."}, {"type": "examples", "items": ["I have got a dog.", "She has got a bike.", "They haven't got a car.", "Has he got a guitar?"]}]$j$::jsonb);
