INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('540d0eae-cf58-5e3b-9495-ac0c43ed5280','52ba9cd7-2a50-5e27-86d3-797dda5eeb5d','Possessive adjectives',0,'LESSON',70,$j$[{"type": "rule", "text": "Possessive adjectives show who something belongs to: my, your, his, her, its, our, your, their."}, {"type": "rule", "text": "A possessive adjective comes before a noun: my book, her cat, their house."}, {"type": "examples", "items": ["This is my pen.", "That is her bag.", "Our school is big.", "Their dog is friendly."]}]$j$::jsonb);
