INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('93b6db6b-d905-57e9-a3ca-f7698d2f264d','a0000000-0000-4000-8000-000000000051','Блок 6. Plurals',6,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('7c51c422-74f5-5602-b94f-3d0387ce71fd','93b6db6b-d905-57e9-a3ca-f7698d2f264d','Plurals',0,'LESSON',70,$j$[{"type": "rule", "text": "Most nouns: add -s. cat -> cats, book -> books."}, {"type": "rule", "text": "Nouns ending in -s, -ss, -x, -ch, -sh: add -es. bus -> buses, box -> boxes, watch -> watches."}, {"type": "rule", "text": "Nouns ending in consonant + y: change y to -ies. baby -> babies, city -> cities."}, {"type": "rule", "text": "Nouns ending in -f or -fe: change to -ves. leaf -> leaves, knife -> knives."}, {"type": "rule", "text": "Irregular plurals: man -> men, woman -> women, child -> children, foot -> feet, tooth -> teeth, mouse -> mice."}, {"type": "examples", "items": ["one pen, two pens", "one bus, two buses", "one baby, two babies", "one child, two children"]}]$j$::jsonb);
