INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d9eb6633-16e7-596d-a616-c6e8ea9334cf','e50d268e-1e6e-5a20-918d-b6279be7736c','Prepositions of place',0,'LESSON',70,$j$[{"type": "rule", "text": "Prepositions of place show where someone or something is."}, {"type": "text", "text": "Common prepositions of place are: in, on, under, behind, in front of, next to, between."}, {"type": "examples", "items": ["The cat is on the sofa.", "The bag is under the table.", "The tree is behind the house.", "The car is in front of the garage.", "The shop is next to the bank.", "The ball is between the two boxes."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c710ee78-b2de-58c9-8332-60e17d9e4743','d9eb6633-16e7-596d-a616-c6e8ea9334cf',0,'FILL_BLANK','Вставьте правильный предлог места по описанию.',$j${"items": [{"before": "The ball is on top of the box. The ball is", "after": "the box."}, {"before": "The ball is inside the box. The ball is", "after": "the box."}, {"before": "The ball is below the box. The ball is", "after": "the box."}, {"before": "The ball is at the back of the box. The ball is", "after": "the box."}, {"before": "The ball is in the middle of two boxes. The ball is", "after": "the boxes."}]}$j$::jsonb,10);
