INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d49e2479-d26b-5387-b66f-8099bd25c2b8','d9eb6633-16e7-596d-a616-c6e8ea9334cf',1,'CHOOSE','Выберите правильный предлог.',$j${"items": [{"before": "We keep the milk", "after": "the fridge.", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "on"}, {"id": "o3", "label": "under"}]}, {"before": "The picture is", "after": "the wall.", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "on"}, {"id": "o3", "label": "under"}]}, {"before": "My slippers are", "after": "the bed, so I can't see them.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "under"}, {"id": "o3", "label": "in"}]}, {"before": "The teacher stands", "after": "front of the class.", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "on"}, {"id": "o3", "label": "at"}]}, {"before": "The lamp is", "after": "the desk.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "in"}, {"id": "o3", "label": "under"}]}]}$j$::jsonb,10);
