INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('96d61f50-f8e1-50af-bfe9-464ff20806f3','a0000000-0000-4000-8000-000000000051','Блок 13. The possessive case',13,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d793d3d5-34d2-5504-9c3a-2c0630582083','96d61f50-f8e1-50af-bfe9-464ff20806f3','The possessive case',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the possessive case to show that something belongs to someone or that people are related."}, {"type": "rule", "text": "With a singular noun we add an apostrophe and -s ('s): Tom's dog, my sister's bag."}, {"type": "rule", "text": "With a plural noun that ends in -s we add only an apostrophe ('): the boys' room, my parents' car."}, {"type": "rule", "text": "With an irregular plural noun that does not end in -s we add 's: the children's toys, the men's shoes."}, {"type": "examples", "items": ["This is Sarah's puppy.", "These are the girls' bikes.", "Anthony is Lewis Hamilton's father.", "The children's room is very big."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0ca2ca5a-5cb9-56b7-ae87-75d3a752938a','d793d3d5-34d2-5504-9c3a-2c0630582083',0,'FILL_BLANK','Образуйте притяжательный падеж от слова в скобках.',$j${"items": [{"before": "This is ", "after": " ball. (John)"}, {"before": "These are the ", "after": " toys. (children)"}, {"before": "That is my ", "after": " bag. (sister)"}, {"before": "This is the ", "after": " changing room. (boys)"}, {"before": "Those are the ", "after": " books. (students)"}]}$j$::jsonb,10);
