INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('21b108dc-27b7-501f-ab13-976b238add7b','a0000000-0000-4000-8000-000000000051','Блок 14. Present Simple',14,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4ce9a0ed-b662-518d-ab4d-d919f79d6be5','21b108dc-27b7-501f-ab13-976b238add7b','Present Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present simple for habits, daily routines, permanent situations and general truths."}, {"type": "rule", "text": "Affirmative: I / you / we / they + base verb; he / she / it + verb + (e)s."}, {"type": "rule", "text": "Spelling of the third person singular: play -> plays, go -> goes, watch -> watches, study -> studies."}, {"type": "rule", "text": "Negative: I / you / we / they + don't + base verb; he / she / it + doesn't + base verb."}, {"type": "rule", "text": "Interrogative: Do / Does + subject + base verb? Short answers: Yes, I do. / No, he doesn't."}, {"type": "examples", "items": ["I play tennis on Mondays.", "My best friend walks to school.", "He doesn't listen to house music.", "Does the race take three hours?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('50b54090-2d6f-5fb8-9b4f-7bb2a4e2c7df','4ce9a0ed-b662-518d-ab4d-d919f79d6be5',0,'FILL_BLANK','Поставьте глагол в скобках в правильную форму Present Simple.',$j${"items": [{"before": "I ", "after": " tennis on Mondays. (play)"}, {"before": "My best friend ", "after": " to school in the morning. (walk)"}, {"before": "My granddad ", "after": " basketball. (like)"}, {"before": "We ", "after": " in a big house with a garden. (live)"}, {"before": "I ", "after": " around the house. (help)"}, {"before": "My brother ", "after": " early every day to go to the gym. (get up)"}, {"before": "I ", "after": " my homework every day. (do)"}, {"before": "My friends ", "after": " baseball. (play)"}, {"before": "My mum ", "after": " at the weekend. (work)"}, {"before": "My family and I ", "after": " dinner at 8 o'clock every evening. (have)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('50b54090-2d6f-5fb8-9b4f-7bb2a4e2c7df',$j${"items": [{"accept": ["play"]}, {"accept": ["walks"]}, {"accept": ["likes"]}, {"accept": ["live"]}, {"accept": ["help"]}, {"accept": ["gets up"]}, {"accept": ["do"]}, {"accept": ["play"]}, {"accept": ["works"]}, {"accept": ["have"]}]}$j$::jsonb,'');
