INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ae0f3a85-8fdc-59b9-8e61-696b89536104','4ce9a0ed-b662-518d-ab4d-d919f79d6be5',4,'MATCH_PAIRS','Соотнесите вопросы с ответами.',$j${"left": [{"id": "l1", "label": "What does he do?"}, {"id": "l2", "label": "What time does she have breakfast?"}, {"id": "l3", "label": "How does he go to work?"}, {"id": "l4", "label": "Does he go to the gym every day?"}, {"id": "l5", "label": "When does he play football?"}, {"id": "l6", "label": "What does he do in the evening?"}], "right": [{"id": "r1", "label": "He is a vet."}, {"id": "r2", "label": "She has breakfast at 8 o'clock."}, {"id": "r3", "label": "He rides his bike to work."}, {"id": "r4", "label": "No, he doesn't."}, {"id": "r5", "label": "He plays football at the weekend."}, {"id": "r6", "label": "He watches TV in the evening."}]}$j$::jsonb,10);
