INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6450338d-61b3-5bbc-be3b-3af2918ebfe0','4ce9a0ed-b662-518d-ab4d-d919f79d6be5',5,'CHOOSE','Выберите Do или Does.',$j${"items": [{"before": "", "after": " Lewis like playing football?", "options": [{"id": "o1", "label": "Do"}, {"id": "o2", "label": "Does"}]}, {"before": "", "after": " they live in Grenada?", "options": [{"id": "o1", "label": "Do"}, {"id": "o2", "label": "Does"}]}, {"before": "", "after": " he listen to house music?", "options": [{"id": "o1", "label": "Do"}, {"id": "o2", "label": "Does"}]}, {"before": "", "after": " the race take three hours?", "options": [{"id": "o1", "label": "Do"}, {"id": "o2", "label": "Does"}]}, {"before": "", "after": " he earn a lot of money?", "options": [{"id": "o1", "label": "Do"}, {"id": "o2", "label": "Does"}]}]}$j$::jsonb,10);
