INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('6e8669f2-af29-576a-9ca4-5ab1267db622','0fec31a6-2e18-5d8b-b723-b18cbdc1e1d8','Like, love, hate + -ing form',0,'LESSON',70,$j$[{"type": "rule", "text": "After the verbs like, love, hate and enjoy we use the -ing form of the next verb."}, {"type": "rule", "text": "Spelling of the -ing form: cook -> cooking, play -> playing, walk -> walking, go -> going, do -> doing."}, {"type": "examples", "items": ["I like playing football.", "She loves cooking.", "They hate walking to school.", "He doesn't like doing the housework."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0aece3f7-55f4-55c2-ad52-161c1e3b0303','6e8669f2-af29-576a-9ca4-5ab1267db622',0,'FILL_BLANK','Поставьте глагол в скобках в форму -ing.',$j${"items": [{"before": "I like ", "after": " football. (play)"}, {"before": "She loves ", "after": " dinner for us. (cook)"}, {"before": "They hate ", "after": " to school in the rain. (walk)"}, {"before": "He enjoys ", "after": " swimming at the weekend. (go)"}, {"before": "We don't like ", "after": " our homework late. (do)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('0aece3f7-55f4-55c2-ad52-161c1e3b0303',$j${"items": [{"accept": ["playing"]}, {"accept": ["cooking"]}, {"accept": ["walking"]}, {"accept": ["going"]}, {"accept": ["doing"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('35f2beab-c51c-517b-8d0a-2beea7e3b1cd','6e8669f2-af29-576a-9ca4-5ab1267db622',1,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "My sister loves ", "after": " photographs.", "options": [{"id": "o1", "label": "taking"}, {"id": "o2", "label": "to taking"}]}, {"before": "Bob likes ", "after": " cars.", "options": [{"id": "o1", "label": "fixing"}, {"id": "o2", "label": "to fixing"}]}, {"before": "He ", "after": " doing the housework.", "options": [{"id": "o1", "label": "doesn't like"}, {"id": "o2", "label": "doesn't likes"}]}]}$j$::jsonb,10);
