INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('aa45bc41-27ef-5d10-8d28-6c6897550efb','a0000000-0000-4000-8000-000000000051','Блок 16. Adverbs of frequency',16,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('a9c80041-c022-5e85-865c-311a9b68a975','aa45bc41-27ef-5d10-8d28-6c6897550efb','Adverbs of frequency',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs of frequency tell us how often we do something: always (100%), usually, often, sometimes, rarely/seldom, never (0%)."}, {"type": "rule", "text": "Adverbs of frequency go before the main verb but after the verb to be."}, {"type": "examples", "items": ["I always brush my teeth in the morning.", "She is never late for school.", "They sometimes play tennis at the weekend."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b741f27e-76f9-546b-ac63-0fc533c842f1','a9c80041-c022-5e85-865c-311a9b68a975',0,'CHOOSE','Выберите правильный порядок слов.',$j${"items": [{"before": "She ", "after": " late for school.", "options": [{"id": "o1", "label": "is never"}, {"id": "o2", "label": "never is"}]}, {"before": "They ", "after": " go swimming on Sunday.", "options": [{"id": "o1", "label": "often go"}, {"id": "o2", "label": "go often"}]}, {"before": "I ", "after": " tired in the morning.", "options": [{"id": "o1", "label": "am always"}, {"id": "o2", "label": "always am"}]}, {"before": "We ", "after": " watch TV in the evening.", "options": [{"id": "o1", "label": "sometimes watch"}, {"id": "o2", "label": "watch sometimes"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('b741f27e-76f9-546b-ac63-0fc533c842f1',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2fd39419-d0cd-5a40-9233-4300aafdc816','a9c80041-c022-5e85-865c-311a9b68a975',1,'MATCH_PAIRS','Соотнесите наречие частоты с его значением.',$j${"left": [{"id": "l1", "label": "always"}, {"id": "l2", "label": "usually"}, {"id": "l3", "label": "sometimes"}, {"id": "l4", "label": "never"}], "right": [{"id": "r1", "label": "100%"}, {"id": "r2", "label": "80%"}, {"id": "r3", "label": "50%"}, {"id": "r4", "label": "0%"}]}$j$::jsonb,10);
