INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('661b403b-0cdd-50ff-9ae6-3de6039c18fb','a0000000-0000-4000-8000-000000000051','Блок 17. Prepositions of time',17,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('20be2516-9b70-519f-96ee-22fad33f9ec9','661b403b-0cdd-50ff-9ae6-3de6039c18fb','Prepositions of time',0,'LESSON',70,$j$[{"type": "rule", "text": "We use at with clock times, with night and with the weekend: at 7 o'clock, at night, at the weekend."}, {"type": "rule", "text": "We use on with days of the week and with dates: on Monday, on 5th May, on my birthday."}, {"type": "rule", "text": "We use in with months, seasons, years and parts of the day: in July, in summer, in 2010, in the morning."}, {"type": "examples", "items": ["I get up at 7 o'clock.", "We go to school on Monday.", "It is cold in winter."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('cb4dd983-3801-504a-8afe-cc8673aebe8f','20be2516-9b70-519f-96ee-22fad33f9ec9',0,'FILL_BLANK','Вставьте предлог времени at, on или in.',$j${"items": [{"before": "", "after": " Monday"}, {"before": "", "after": " the morning"}, {"before": "", "after": " 7 o'clock"}, {"before": "", "after": " summer"}, {"before": "", "after": " night"}, {"before": "", "after": " my birthday"}, {"before": "", "after": " December"}, {"before": "", "after": " the weekend"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('cb4dd983-3801-504a-8afe-cc8673aebe8f',$j${"items": [{"accept": ["on"]}, {"accept": ["in"]}, {"accept": ["at"]}, {"accept": ["in"]}, {"accept": ["at"]}, {"accept": ["on"]}, {"accept": ["in"]}, {"accept": ["at"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f8e3abca-003f-5a3e-b80c-9bd37cc2d583','20be2516-9b70-519f-96ee-22fad33f9ec9',1,'SORT_COLUMNS','Распределите выражения времени по колонкам.',$j${"columns": [{"id": "c1", "label": "at"}, {"id": "c2", "label": "on"}, {"id": "c3", "label": "in"}], "items": [{"id": "i1", "label": "night"}, {"id": "i2", "label": "Sunday"}, {"id": "i3", "label": "July"}, {"id": "i4", "label": "the weekend"}, {"id": "i5", "label": "the afternoon"}, {"id": "i6", "label": "5th May"}]}$j$::jsonb,10);
