INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('ea70b846-7147-5e17-9713-032f67044d49','a0000000-0000-4000-8000-000000000051','Блок 18. Comparatives - Superlatives',18,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c295696b-32ce-586a-94e0-b77351b1df79','ea70b846-7147-5e17-9713-032f67044d49','Comparatives - Superlatives',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the comparative to compare two people or things, and the superlative to compare three or more."}, {"type": "rule", "text": "Short adjectives: add -er for the comparative and the ... -est for the superlative (tall -> taller -> the tallest)."}, {"type": "rule", "text": "Adjectives ending in -y: change y to i, then add -er / the ... -est (happy -> happier -> the happiest)."}, {"type": "rule", "text": "Longer adjectives: use more before the comparative and the most before the superlative (expensive -> more expensive -> the most expensive)."}, {"type": "rule", "text": "Irregular forms: good -> better -> the best; bad -> worse -> the worst."}, {"type": "rule", "text": "We use than after a comparative and the before a superlative."}, {"type": "examples", "items": ["An elephant is bigger than a dog.", "This book is more interesting than that one.", "The elephant is the biggest animal here.", "This is the best film I know."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2a371095-667d-5991-a263-4c36be273f7f','c295696b-32ce-586a-94e0-b77351b1df79',0,'FILL_BLANK','Образуйте сравнительную степень прилагательного в скобках.',$j${"items": [{"before": "An elephant is ", "after": " than a dog. (big)"}, {"before": "This book is ", "after": " than that one. (interesting)"}, {"before": "She is ", "after": " than her brother. (happy)"}, {"before": "A car is ", "after": " than a bike. (fast)"}, {"before": "Maths is ", "after": " than art. (difficult)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('2a371095-667d-5991-a263-4c36be273f7f',$j${"items": [{"accept": ["bigger"]}, {"accept": ["more interesting"]}, {"accept": ["happier"]}, {"accept": ["faster"]}, {"accept": ["more difficult"]}]}$j$::jsonb,'');
