INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('fa4b9c60-34a9-5acf-9c9e-9c4661e2d1c9','a0000000-0000-4000-8000-000000000051','Блок 19. Adverbs of degree',19,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('5fc9d837-c9e4-5eb1-93a0-c96470b3fb34','fa4b9c60-34a9-5acf-9c9e-9c4661e2d1c9','Adverbs of degree',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs of degree tell us how much or to what degree: very, really, quite, too, enough."}, {"type": "rule", "text": "very, really, quite and too go before an adjective: very big, too small, quite tall."}, {"type": "rule", "text": "enough goes after the adjective: big enough, old enough."}, {"type": "rule", "text": "too means 'more than we want'; enough means 'as much as we need'."}, {"type": "examples", "items": ["The elephant is very big.", "The rabbit is too small to carry the box.", "He isn't tall enough to reach the shelf."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5d0e41c2-08a8-5114-8310-2b7501a3f5b0','5fc9d837-c9e4-5eb1-93a0-c96470b3fb34',0,'CHOOSE','Выберите правильное наречие степени.',$j${"items": [{"before": "The elephant is ", "after": " big.", "options": [{"id": "o1", "label": "very"}, {"id": "o2", "label": "enough"}]}, {"before": "This box isn't big ", "after": " to hold all the toys.", "options": [{"id": "o1", "label": "enough"}, {"id": "o2", "label": "very"}]}, {"before": "The coffee is ", "after": " hot to drink.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "She is ", "after": " tall for her age.", "options": [{"id": "o1", "label": "quite"}, {"id": "o2", "label": "enough"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5d0e41c2-08a8-5114-8310-2b7501a3f5b0',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('06d262ee-8f14-527f-a218-e323beb9687c','5fc9d837-c9e4-5eb1-93a0-c96470b3fb34',1,'FILL_BLANK','Вставьте very, too или enough.',$j${"items": [{"before": "The film was ", "after": " good. I loved it."}, {"before": "I can't buy it. It's ", "after": " expensive."}, {"before": "He isn't old ", "after": " to drive a car."}]}$j$::jsonb,10);
