INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('1119c012-ba31-5fe4-8613-180844deac4c','a0000000-0000-4000-8000-000000000051','Блок 20. Question words',20,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('57d68a12-e45b-5125-ab08-4a58ae6a49f5','1119c012-ba31-5fe4-8613-180844deac4c','Question words',0,'LESSON',70,$j$[{"type": "rule", "text": "We use question words to ask for information: What, Who, Where, When, Why, How, Which, Whose."}, {"type": "rule", "text": "What asks about a thing, Who about a person, Where about a place, When about time, Why about a reason, How about the way something happens."}, {"type": "rule", "text": "Whose asks about possession; How many asks about number; How much asks about quantity or price."}, {"type": "examples", "items": ["What is your name?", "Where do you live?", "Why are you late?", "Whose handbag is this?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ea6d4f7c-1ead-522c-912a-9671f8d8e1fb','57d68a12-e45b-5125-ab08-4a58ae6a49f5',0,'FILL_BLANK','Вставьте подходящее вопросительное слово.',$j${"items": [{"before": "", "after": " is your name? Tom."}, {"before": "", "after": " do you live? In London."}, {"before": "", "after": " is your birthday? In May."}, {"before": "", "after": " are you late? Because I missed the bus."}, {"before": "", "after": " old are you? I'm twelve."}, {"before": "", "after": " is that boy? He's my brother."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('ea6d4f7c-1ead-522c-912a-9671f8d8e1fb',$j${"items": [{"accept": ["What"]}, {"accept": ["Where"]}, {"accept": ["When"]}, {"accept": ["Why"]}, {"accept": ["How"]}, {"accept": ["Who"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8e568a17-be31-5ddc-baed-dd71b455c2d6','57d68a12-e45b-5125-ab08-4a58ae6a49f5',1,'MATCH_PAIRS','Соотнесите вопросы с ответами.',$j${"left": [{"id": "l1", "label": "Where do you live?"}, {"id": "l2", "label": "When is the party?"}, {"id": "l3", "label": "Who is she?"}, {"id": "l4", "label": "How are you?"}, {"id": "l5", "label": "What is this?"}], "right": [{"id": "r1", "label": "In Astana."}, {"id": "r2", "label": "On Saturday."}, {"id": "r3", "label": "My sister."}, {"id": "r4", "label": "I'm fine, thanks."}, {"id": "r5", "label": "It's a pen."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('8e568a17-be31-5ddc-baed-dd71b455c2d6',$j${"pairs": [{"l": "l1", "r": "r1"}, {"l": "l2", "r": "r2"}, {"l": "l3", "r": "r3"}, {"l": "l4", "r": "r4"}, {"l": "l5", "r": "r5"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c11ccffc-c1a2-5c0e-80d2-7fa4c16dc7b3','57d68a12-e45b-5125-ab08-4a58ae6a49f5',2,'CHOOSE','Выберите правильное вопросительное слово.',$j${"items": [{"before": "", "after": " handbag is this? Sue's.", "options": [{"id": "o1", "label": "Whose"}, {"id": "o2", "label": "Who's"}]}, {"before": "", "after": " much is the ticket?", "options": [{"id": "o1", "label": "How"}, {"id": "o2", "label": "What"}]}, {"before": "", "after": " colour is your car?", "options": [{"id": "o1", "label": "What"}, {"id": "o2", "label": "Who"}]}]}$j$::jsonb,10);
