INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('c22b5c2c-154d-568c-ae51-c3de027a3ce4','a0000000-0000-4000-8000-000000000051','Блок 21. Present Continuous',21,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d692dab5-b92c-593d-841a-ddf6598d5247','c22b5c2c-154d-568c-ae51-c3de027a3ce4','Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the Present Continuous to talk about actions happening now, at the moment of speaking. We form it with am/is/are + the -ing form of the verb: I am reading, He is running, They are playing."}, {"type": "rule", "text": "Negative: I am not (I'm not), he is not (isn't), they are not (aren't) + -ing. Interrogative: Am I ...? Is he ...? Are they ...? Short answers: Yes, I am. / No, he isn't."}, {"type": "rule", "text": "Spelling of the -ing form: most verbs just add -ing (play - playing). Verbs ending in -e drop the -e and add -ing (make - making). Short verbs ending in one vowel + one consonant double the consonant and add -ing (sit - sitting, swim - swimming)."}, {"type": "examples", "items": ["Tony is riding a bike.", "Sandy and Julie are walking in the park.", "Steve is reading a newspaper.", "The children are playing football."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('89d9e61a-7ce8-555b-9e78-ac751d6f7994','d692dab5-b92c-593d-841a-ddf6598d5247',0,'FILL_BLANK','Напишите форму -ing данного глагола.',$j${"items": [{"before": "play - ", "after": ""}, {"before": "make - ", "after": ""}, {"before": "run - ", "after": ""}, {"before": "swim - ", "after": ""}, {"before": "write - ", "after": ""}, {"before": "read - ", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('89d9e61a-7ce8-555b-9e78-ac751d6f7994',$j${"items": [{"accept": ["playing"]}, {"accept": ["making"]}, {"accept": ["running"]}, {"accept": ["swimming"]}, {"accept": ["writing"]}, {"accept": ["reading"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('bcaee3c8-3486-5f5a-81db-fce50ff05bd5','d692dab5-b92c-593d-841a-ddf6598d5247',1,'SORT_COLUMNS','Распределите глаголы по правилу образования формы -ing.',$j${"columns": [{"id": "c1", "label": "+ -ing"}, {"id": "c2", "label": "drop -e + -ing"}, {"id": "c3", "label": "double consonant + -ing"}], "items": [{"id": "i1", "label": "watch"}, {"id": "i2", "label": "dance"}, {"id": "i3", "label": "sit"}, {"id": "i4", "label": "play"}, {"id": "i5", "label": "write"}, {"id": "i6", "label": "run"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('bcaee3c8-3486-5f5a-81db-fce50ff05bd5',$j${"placement": {"i1": "c1", "i2": "c2", "i3": "c3", "i4": "c1", "i5": "c2", "i6": "c3"}}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6b80a943-e8d4-5f9f-a735-9a647ae884c5','d692dab5-b92c-593d-841a-ddf6598d5247',2,'CHOOSE','Выберите правильную форму глагола to be (am / is / are).',$j${"items": [{"before": "I", "after": "reading a book.", "options": [{"id": "o1", "label": "am"}, {"id": "o2", "label": "is"}]}, {"before": "Tony", "after": "riding a bike.", "options": [{"id": "o1", "label": "are"}, {"id": "o2", "label": "is"}]}, {"before": "Sandy and Julie", "after": "walking.", "options": [{"id": "o1", "label": "are"}, {"id": "o2", "label": "is"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('6b80a943-e8d4-5f9f-a735-9a647ae884c5',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f5761584-04ba-5b06-905e-c87298080f8e','d692dab5-b92c-593d-841a-ddf6598d5247',3,'FILL_BLANK','Раскройте скобки, используя Present Continuous.',$j${"items": [{"before": "Look! Steve ", "after": " (read) a newspaper."}, {"before": "The children ", "after": " (play) football now."}, {"before": "I ", "after": " (drink) a cup of coffee at the moment."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f5761584-04ba-5b06-905e-c87298080f8e',$j${"items": [{"accept": ["is reading"]}, {"accept": ["are playing"]}, {"accept": ["am drinking", "'m drinking"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('02a3a1e7-9360-5d80-b2ad-4a9c0a57e284','a0000000-0000-4000-8000-000000000051','Блок 22. Present Simple vs Present Continuous',22,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('5fbafbcf-4051-524a-ae18-3c6c4a07d2f8','02a3a1e7-9360-5d80-b2ad-4a9c0a57e284','Present Simple vs Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the Present Simple for permanent states, habits and routines, and things that are always true: Angela lives in the city. They go there every winter. It snows every night."}, {"type": "rule", "text": "We use the Present Continuous for actions happening at the time of speaking and for fixed arrangements in the near future: They are staying at a hotel now. They are leaving tomorrow."}, {"type": "rule", "text": "Time expressions with the Present Simple: every day, usually, always, often, sometimes, never. Time expressions with the Present Continuous: now, at the moment, today, tonight, tomorrow."}, {"type": "examples", "items": ["Angela loves skiing, so they go there every winter.", "The skies are bright blue today.", "They usually go skiing in the morning.", "Today they are planning to buy souvenirs."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d678208e-f7d4-58bc-8c69-8dff8048c67d','5fbafbcf-4051-524a-ae18-3c6c4a07d2f8',0,'FILL_BLANK','Раскройте скобки, употребив Present Simple или Present Continuous.',$j${"items": [{"before": "A: Why ", "after": " (you/sit) in here?"}, {"before": "B: Because it ", "after": " (snow) outside."}, {"before": "A: How often ", "after": " (you/meet) your friends?"}, {"before": "B: I ", "after": " (meet) them every weekend."}, {"before": "A: What ", "after": " (you/do) on Saturdays?"}, {"before": "B: I always ", "after": " (play) football."}, {"before": "A: Where are Angela and her friends? B: They ", "after": " (study) in the library."}, {"before": "A: I'm sorry, I can't come. I ", "after": " (visit) my grandparents tomorrow."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('d678208e-f7d4-58bc-8c69-8dff8048c67d',$j${"items": [{"accept": ["are you sitting"]}, {"accept": ["is snowing"]}, {"accept": ["do you meet"]}, {"accept": ["meet"]}, {"accept": ["do you do"]}, {"accept": ["play"]}, {"accept": ["are studying"]}, {"accept": ["am visiting", "'m visiting"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c14168f9-09a3-5d9f-aaf3-5a3a9964b6dd','5fbafbcf-4051-524a-ae18-3c6c4a07d2f8',1,'CHOOSE','Выберите правильную форму глагола.',$j${"items": [{"before": "Angela usually", "after": "skiing in the morning.", "options": [{"id": "o1", "label": "goes"}, {"id": "o2", "label": "is going"}]}, {"before": "Look! It", "after": "outside.", "options": [{"id": "o1", "label": "snows"}, {"id": "o2", "label": "is snowing"}]}, {"before": "They", "after": "dinner in a restaurant tonight.", "options": [{"id": "o1", "label": "have"}, {"id": "o2", "label": "are having"}]}, {"before": "It", "after": "on the mountain every night.", "options": [{"id": "o1", "label": "snows"}, {"id": "o2", "label": "is snowing"}]}]}$j$::jsonb,10);
