INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('51250172-3567-5c23-93c8-d37599cdacc4','a0000000-0000-4000-8000-000000000051','Блок 23. Countable/Uncountable nouns',23,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('650870b8-2789-56cb-b1f6-0e2f16f40171','51250172-3567-5c23-93c8-d37599cdacc4','Countable/Uncountable nouns',0,'LESSON',70,$j$[{"type": "rule", "text": "Countable nouns are things we can count. They have a singular and a plural form: a pear - two pears, an apple - three apples. We can use a/an with them in the singular."}, {"type": "rule", "text": "Uncountable nouns are things we cannot count separately, such as liquids, materials and substances: rice, cheese, water, milk, bread, sugar. They have no plural form and we do not use a/an with them. We say some rice, some cheese."}, {"type": "examples", "items": ["There is a pear on the table.", "There are three pears in the bowl.", "There is some rice in the bowl.", "There is some cheese on the plate."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('80ea5f02-5dda-5b08-b3cc-e4243ae53e9b','650870b8-2789-56cb-b1f6-0e2f16f40171',0,'SORT_COLUMNS','Распределите существительные на исчисляемые и неисчисляемые.',$j${"columns": [{"id": "c1", "label": "Countable"}, {"id": "c2", "label": "Uncountable"}], "items": [{"id": "i1", "label": "pear"}, {"id": "i2", "label": "rice"}, {"id": "i3", "label": "apple"}, {"id": "i4", "label": "cheese"}, {"id": "i5", "label": "egg"}, {"id": "i6", "label": "water"}, {"id": "i7", "label": "banana"}, {"id": "i8", "label": "milk"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('80ea5f02-5dda-5b08-b3cc-e4243ae53e9b',$j${"placement": {"i1": "c1", "i2": "c2", "i3": "c1", "i4": "c2", "i5": "c1", "i6": "c2", "i7": "c1", "i8": "c2"}}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f35f09b3-10d7-595d-b883-2f27ad485124','650870b8-2789-56cb-b1f6-0e2f16f40171',1,'CHOOSE','Выберите правильный вариант (a / some).',$j${"items": [{"before": "There is", "after": "pear on the plate.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}]}, {"before": "There is", "after": "rice in the bowl.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}]}, {"before": "There is", "after": "cheese on the table.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}]}, {"before": "There is", "after": "egg in the fridge.", "options": [{"id": "o1", "label": "an"}, {"id": "o2", "label": "some"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f35f09b3-10d7-595d-b883-2f27ad485124',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4accfd4c-7937-5e81-bb89-ec0c86982fe2','650870b8-2789-56cb-b1f6-0e2f16f40171',2,'CHOOSE','Выберите правильную форму глагола (is / are).',$j${"items": [{"before": "There", "after": "some milk in the glass.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}]}, {"before": "There", "after": "three pears in the bowl.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}]}, {"before": "There", "after": "some rice on the plate.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('4accfd4c-7937-5e81-bb89-ec0c86982fe2',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('dd43e3e5-76c7-5d1d-9ad3-86d014f82d03','a0000000-0000-4000-8000-000000000051','Блок 24. A/An - Some/Any',24,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('ee6a6baa-c9e1-5343-8dc0-a9fea5ca7b4d','dd43e3e5-76c7-5d1d-9ad3-86d014f82d03','A/An - Some/Any',0,'LESSON',70,$j$[{"type": "rule", "text": "We use a/an with singular countable nouns: a cake, an orange, an egg. We use a before a consonant sound and an before a vowel sound."}, {"type": "rule", "text": "We use some in affirmative sentences with plural countable nouns and with uncountable nouns: There are some biscuits. There is some bread."}, {"type": "rule", "text": "We use any in negative and interrogative sentences: There aren't any eggs. Is there any juice? Are there any tomatoes?"}, {"type": "examples", "items": ["There is an orange in the basket.", "There is some bread on the table.", "There aren't any biscuits left.", "Are there any tomatoes in the sauce?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c7856db1-7f51-5351-bf78-891c65199a82','ee6a6baa-c9e1-5343-8dc0-a9fea5ca7b4d',0,'FILL_BLANK','Вставьте a или an.',$j${"items": [{"before": "", "after": "orange"}, {"before": "", "after": "cake"}, {"before": "", "after": "egg"}, {"before": "", "after": "biscuit"}, {"before": "", "after": "apple"}, {"before": "", "after": "pizza"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c7856db1-7f51-5351-bf78-891c65199a82',$j${"items": [{"accept": ["an"]}, {"accept": ["a"]}, {"accept": ["an"]}, {"accept": ["a"]}, {"accept": ["an"]}, {"accept": ["a"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('775bd516-9d1f-5b8d-887a-152c102a2c45','ee6a6baa-c9e1-5343-8dc0-a9fea5ca7b4d',1,'CHOOSE','Выберите some или any.',$j${"items": [{"before": "There is", "after": "bread on the table.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "There aren't", "after": "eggs in the fridge.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Are there", "after": "tomatoes in the sauce?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "I have got", "after": "cereal for breakfast.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Is there", "after": "juice in the glass?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('775bd516-9d1f-5b8d-887a-152c102a2c45',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('1e1bc951-451b-5ae4-a820-3d47fb77f35d','ee6a6baa-c9e1-5343-8dc0-a9fea5ca7b4d',2,'FILL_BLANK','Вставьте some или any.',$j${"items": [{"before": "There are ", "after": " biscuits on the plate."}, {"before": "There isn't ", "after": " milk in the bottle."}, {"before": "Have we got ", "after": " bread?"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('1e1bc951-451b-5ae4-a820-3d47fb77f35d',$j${"items": [{"accept": ["some"]}, {"accept": ["any"]}, {"accept": ["any"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('79769834-aea1-5bc8-890d-f60152fdb3a8','a0000000-0000-4000-8000-000000000051','Блок 25. Much/Many - A lot of - A few/A little',25,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('62f0a1a7-232e-5ad2-a41d-1d7a7c352d4a','79769834-aea1-5bc8-890d-f60152fdb3a8','Much/Many - A lot of - A few/A little',0,'LESSON',70,$j$[{"type": "rule", "text": "We use many and a few with plural countable nouns: many apples, a few eggs. We use much and a little with uncountable nouns: much water, a little cheese."}, {"type": "rule", "text": "We usually use much and many in questions and negative sentences: Are there many strawberries? There isn't much milk. In affirmative sentences we usually use a lot of, which goes with both countable and uncountable nouns: a lot of apples, a lot of water."}, {"type": "rule", "text": "A few / a little mean 'a small amount that is enough'. A few is for countable nouns, a little is for uncountable nouns: There are a few eggs. There is a little milk."}, {"type": "examples", "items": ["There are a lot of strawberries in the basket.", "There isn't much cheese left.", "How many apples are there?", "We need a little sugar for the cake."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('55cb9dbe-a157-557d-a3a7-d7236989066d','62f0a1a7-232e-5ad2-a41d-1d7a7c352d4a',0,'CHOOSE','Выберите much или many.',$j${"items": [{"before": "How", "after": "apples are there?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "There isn't", "after": "milk in the bottle.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "How", "after": "cheese do you want?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "There aren't", "after": "eggs in the fridge.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('55cb9dbe-a157-557d-a3a7-d7236989066d',$j${"items": [{"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d4d36ffd-14ba-534c-827b-6eddb78f81ff','62f0a1a7-232e-5ad2-a41d-1d7a7c352d4a',1,'CHOOSE','Выберите a few или a little.',$j${"items": [{"before": "There are", "after": "strawberries in the bowl.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "We need", "after": "sugar for the cake.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "There is", "after": "milk in the glass.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "I have got", "after": "apples in my bag.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('d4d36ffd-14ba-534c-827b-6eddb78f81ff',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('78a430d3-0767-5d41-95dd-8fae866a8569','62f0a1a7-232e-5ad2-a41d-1d7a7c352d4a',2,'SORT_COLUMNS','Распределите слова по типу существительного, с которым они употребляются.',$j${"columns": [{"id": "c1", "label": "with countable (plural)"}, {"id": "c2", "label": "with uncountable"}], "items": [{"id": "i1", "label": "many"}, {"id": "i2", "label": "much"}, {"id": "i3", "label": "a few"}, {"id": "i4", "label": "a little"}]}$j$::jsonb,10);
