INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('55a0b95b-30be-5c97-9d31-7767f63cc99d','a0000000-0000-4000-8000-000000000051','Блок 26. Be going to & Will',26,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('e9150ed0-5c26-5853-870f-71c96f0395b4','55a0b95b-30be-5c97-9d31-7767f63cc99d','Be going to & Will',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'be going to' (+ bare infinitive) to talk about future plans and intentions and to make predictions based on what we can see or know now."}, {"type": "rule", "text": "We use 'will' (+ bare infinitive) for on-the-spot decisions, predictions based on what we think or imagine, promises, threats and warnings."}, {"type": "examples", "items": ["I'm going to visit my grandparents next week. (plan)", "Look at those clouds! It's going to rain. (prediction from evidence)", "I'll open the door for you. (on-the-spot decision)", "I think it will snow tomorrow. (prediction / opinion)", "Stop that or I'll call the police! (threat)"]}]$j$::jsonb);
