INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b55894a4-8f6e-54d9-aea9-5ebbaa0eeb10','bd7dcaba-87b7-5073-9b87-67503385fbea','Must/Mustn''t - Can/Can''t - Have to/Don''t have to',0,'LESSON',70,$j$[{"type": "rule", "text": "'Must' expresses obligation or necessity; 'mustn't' expresses prohibition (it is not allowed)."}, {"type": "rule", "text": "'Can' expresses ability or permission; 'can't' expresses inability or that something is not allowed."}, {"type": "rule", "text": "'Have to/has to' expresses necessity; 'don't/doesn't have to' means it is not necessary (there is no obligation)."}, {"type": "examples", "items": ["You must wear a seatbelt in the car.", "You mustn't smoke in here.", "She can swim very well.", "You can't park here.", "I have to get up early for school.", "You don't have to pay; it's free."]}]$j$::jsonb);
