INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('45798900-d94c-5e91-a2ec-170f88605506','79f3de94-f4e7-5eb7-849c-587e3d975380','Could',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'could' to talk about past ability (what someone was able to do) and to make polite requests."}, {"type": "rule", "text": "Negative: couldn't (could not). Questions: Could you...? Short answers: Yes, I could. / No, I couldn't."}, {"type": "examples", "items": ["She could swim when she was four.", "I couldn't ride a bike.", "Could you open the window, please?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('02a8024a-43be-556f-94c8-0074bb45b25d','45798900-d94c-5e91-a2ec-170f88605506',0,'FILL_BLANK','Заполните пропуски: ''could'' или ''couldn''t''.',$j${"items": [{"before": "When she was five, she", "after": "read and write."}, {"before": "The room was dark, so I", "after": "see anything."}, {"before": "He was a great athlete; he", "after": "run very fast."}, {"before": "The baby", "after": "walk yet; she was only six months old."}, {"before": "My grandfather", "after": "speak three languages."}]}$j$::jsonb,10);
