INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('793e0530-dab1-5e54-abbf-f5ff05b158ba','938b9f8f-c144-53e8-ad92-aed15632d4ae','There was/There were',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'There was' with singular nouns and 'There were' with plural nouns to say that something existed in the past."}, {"type": "rule", "text": "Negative: There wasn't / There weren't. Questions: Was there...? Were there...?"}, {"type": "examples", "items": ["There was a castle on the hill.", "There were many people at the beach.", "There wasn't any milk.", "Were there any shops?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('780b8460-00e0-5f52-b0a0-900eda7592be','793e0530-dab1-5e54-abbf-f5ff05b158ba',0,'FILL_BLANK','Заполните пропуски: ''There was'' или ''There were''.',$j${"items": [{"before": "", "after": "a big tower in Blackpool."}, {"before": "", "after": "a lot of people on the beach."}, {"before": "", "after": "an old bed in the room."}, {"before": "", "after": "two lamps next to the bed."}, {"before": "", "after": "a beautiful carpet on the floor."}, {"before": "", "after": "many old houses along the street."}]}$j$::jsonb,10);
