INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('63516c60-522f-587a-9455-5218735be9bb','a0000000-0000-4000-8000-000000000051','Блок 32. Past Simple (regular verbs)',32,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('86a8aa70-2c98-5b1b-b7a5-12aa282d8880','63516c60-522f-587a-9455-5218735be9bb','Past Simple (regular verbs)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the Past Simple for actions that started and finished in the past. We usually add -ed to regular verbs: work → worked, play → played, watch → watched."}, {"type": "rule", "text": "Spelling: verbs ending in -e add only -d (live → lived); consonant + y changes to -ied (study → studied); a short vowel + one consonant doubles the consonant (stop → stopped)."}, {"type": "rule", "text": "Negative: subject + didn't + base verb (I didn't play). Question: Did + subject + base verb? (Did you play?). Short answers: Yes, I did. / No, I didn't."}, {"type": "examples", "items": ["She watered the garden.", "They didn't visit their friends.", "Did you watch TV? Yes, I did."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('1136de5d-8f74-5e6b-9849-6ea9c54f466a','86a8aa70-2c98-5b1b-b7a5-12aa282d8880',0,'FILL_BLANK','Поставьте глаголы в скобках в Past Simple.',$j${"items": [{"before": "El Greco (live)", "after": "on the island of Crete."}, {"before": "He (train)", "after": "to be an artist."}, {"before": "At the age of 26, he (travel)", "after": "to Venice."}, {"before": "He (move)", "after": "to Rome."}, {"before": "He (open)", "after": "his own workshop."}, {"before": "Eventually he (decide)", "after": "to go to Spain."}, {"before": "The people there (love)", "after": "his work."}, {"before": "He (stay)", "after": "there until he died in 1614."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('1136de5d-8f74-5e6b-9849-6ea9c54f466a',$j${"items": [{"accept": ["lived"]}, {"accept": ["trained"]}, {"accept": ["travelled", "traveled"]}, {"accept": ["moved"]}, {"accept": ["opened"]}, {"accept": ["decided"]}, {"accept": ["loved"]}, {"accept": ["stayed"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c65ee2a1-81b6-542e-89eb-34d36f0118b3','86a8aa70-2c98-5b1b-b7a5-12aa282d8880',1,'CHOOSE','Выберите правильную форму (утвердительную или отрицательную) по значкам ✓/✗.',$j${"items": [{"before": "Molly", "after": "the garden. (✓)", "options": [{"id": "o1", "label": "watered"}, {"id": "o2", "label": "didn't water"}]}, {"before": "Molly", "after": "her room. (✗)", "options": [{"id": "o1", "label": "tidied"}, {"id": "o2", "label": "didn't tidy"}]}, {"before": "Molly", "after": "tennis with Curtis. (✓)", "options": [{"id": "o1", "label": "played"}, {"id": "o2", "label": "didn't play"}]}, {"before": "Molly", "after": "her friends. (✗)", "options": [{"id": "o1", "label": "visited"}, {"id": "o2", "label": "didn't visit"}]}, {"before": "Molly", "after": "TV. (✓)", "options": [{"id": "o1", "label": "watched"}, {"id": "o2", "label": "didn't watch"}]}, {"before": "Molly", "after": "dinner. (✗)", "options": [{"id": "o1", "label": "cooked"}, {"id": "o2", "label": "didn't cook"}]}, {"before": "Molly", "after": "to music. (✓)", "options": [{"id": "o1", "label": "listened"}, {"id": "o2", "label": "didn't listen"}]}]}$j$::jsonb,10);
