INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('810301b1-a3e6-5aac-96b1-1d9944398836','86a8aa70-2c98-5b1b-b7a5-12aa282d8880',2,'MATCH_PAIRS','Сопоставьте вопросы с ответами.',$j${"left": [{"id": "l1", "label": "What time did you return home from school yesterday?"}, {"id": "l2", "label": "Where did Mark play basketball last Tuesday?"}, {"id": "l3", "label": "What did your mum cook for dinner last night?"}, {"id": "l4", "label": "What did you study yesterday morning?"}, {"id": "l5", "label": "Who did you visit last weekend?"}, {"id": "l6", "label": "When did Paul travel to France?"}, {"id": "l7", "label": "How many emails did Sarah receive last month?"}, {"id": "l8", "label": "When did Anna start learning English?"}], "right": [{"id": "r1", "label": "At 4 o'clock."}, {"id": "r2", "label": "At the park."}, {"id": "r3", "label": "Chicken and rice."}, {"id": "r4", "label": "Maths."}, {"id": "r5", "label": "Grandma and granddad."}, {"id": "r6", "label": "Last month."}, {"id": "r7", "label": "Eight."}, {"id": "r8", "label": "When she was 7 years old."}]}$j$::jsonb,10);
