INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('84d0b466-4ddc-5cdd-aabe-e3271d74bcd6','a0000000-0000-4000-8000-000000000051','Блок 33. Past Simple (irregular verbs)',33,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('fe231104-7384-51f8-8574-3defe0f2c44e','84d0b466-4ddc-5cdd-aabe-e3271d74bcd6','Past Simple (irregular verbs)',0,'LESSON',70,$j$[{"type": "rule", "text": "Many common verbs are irregular in the Past Simple. They do not add -ed and you must learn their forms: go → went, have → had, eat → ate, see → saw, make → made, buy → bought, meet → met, take → took, leave → left."}, {"type": "rule", "text": "The negative and question use the base verb, just like regular verbs: didn't + base verb (I didn't go), Did + subject + base verb? (Did you go?)."}, {"type": "examples", "items": ["I went to the shops.", "He didn't buy a car.", "Did you have lunch? Yes, I did."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6e597bcb-d597-563d-9b70-f901aaf27961','fe231104-7384-51f8-8574-3defe0f2c44e',0,'FILL_BLANK','Поставьте глаголы в скобках в Past Simple.',$j${"items": [{"before": "I (eat)", "after": "an apple and a sandwich."}, {"before": "She (wake up)", "after": "late."}, {"before": "So she (take)", "after": "a taxi."}, {"before": "No, I (stay)", "after": "in and played computer games."}, {"before": "He (leave)", "after": "at 8 o'clock this morning."}, {"before": "I (go)", "after": "to the shops with my sister."}, {"before": "Then we (meet)", "after": "some friends."}, {"before": "I (buy)", "after": "a black dress last month."}, {"before": "I just (watch)", "after": "a DVD."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('6e597bcb-d597-563d-9b70-f901aaf27961',$j${"items": [{"accept": ["ate"]}, {"accept": ["woke up"]}, {"accept": ["took"]}, {"accept": ["stayed"]}, {"accept": ["left"]}, {"accept": ["went"]}, {"accept": ["met"]}, {"accept": ["bought"]}, {"accept": ["watched"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e6307cd8-6e5c-5fc9-b964-15fe7dc38fbb','fe231104-7384-51f8-8574-3defe0f2c44e',1,'CHOOSE','Выберите правильную форму глагола.',$j${"items": [{"before": "Barry didn't go to China last summer. He", "after": "to India.", "options": [{"id": "o1", "label": "went"}, {"id": "o2", "label": "goed"}]}, {"before": "Peter didn't rent a motorbike. He", "after": "a car.", "options": [{"id": "o1", "label": "rented"}, {"id": "o2", "label": "rent"}]}, {"before": "Janice didn't see a horror film. She", "after": "a comedy.", "options": [{"id": "o1", "label": "saw"}, {"id": "o2", "label": "seed"}]}, {"before": "Mark didn't play polo. He", "after": "tennis.", "options": [{"id": "o1", "label": "played"}, {"id": "o2", "label": "play"}]}, {"before": "Mr & Mrs Lawson didn't go to the park. They", "after": "to a restaurant.", "options": [{"id": "o1", "label": "went"}, {"id": "o2", "label": "goed"}]}]}$j$::jsonb,10);
