INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('afc90474-90a7-5bcd-8219-ba10ea09a6a0','fe231104-7384-51f8-8574-3defe0f2c44e',2,'FILL_BLANK','Заполните пропуски в письме, поставив глаголы в Past Simple.',$j${"items": [{"before": "I'm glad you (have)", "after": "a nice time in Spain."}, {"before": "Last month I (go)", "after": "to an extreme sports camp in Wales."}, {"before": "At first I (make)", "after": "lots of mistakes."}, {"before": "I even (fall)", "after": "a few times."}, {"before": "I (spend)", "after": "six days at the camp."}, {"before": "I (meet)", "after": "a lot of nice people."}]}$j$::jsonb,10);
