INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('779dea38-30d1-568b-aa34-9e2e39f90cfd','34565c75-6c67-5462-b287-ffd4453cf0e9','Revision (Units 26-27)',0,'LESSON',70,$j$[{"type": "text", "text": "Повторение изученного материала: will / be going to, must / mustn't / have to, can / can't, much / many, a / an, some / any, предлоги и местоимения."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0e9594ae-36fc-5c36-a563-6442749a5c23','779dea38-30d1-568b-aa34-9e2e39f90cfd',0,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "We have", "after": "vegetables left. Let's make a soup.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}, {"id": "o3", "label": "a lot"}]}, {"before": "'", "after": "is Mark?' 'My brother's best friend.'", "options": [{"id": "o1", "label": "How"}, {"id": "o2", "label": "Who"}, {"id": "o3", "label": "Whose"}]}, {"before": "We", "after": "go inside. It's not safe.", "options": [{"id": "o1", "label": "must"}, {"id": "o2", "label": "mustn't"}, {"id": "o3", "label": "can"}]}, {"before": "He always", "after": "up early in the morning.", "options": [{"id": "o1", "label": "gets"}, {"id": "o2", "label": "get"}, {"id": "o3", "label": "is getting"}]}, {"before": "I'm really thirsty. I", "after": "some orange juice.", "options": [{"id": "o1", "label": "will get"}, {"id": "o2", "label": "am going to get"}, {"id": "o3", "label": "get"}]}, {"before": "This is", "after": "apple pie.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}, {"id": "o3", "label": "the"}]}, {"before": "That's not Bill's car.", "after": "car is blue.", "options": [{"id": "o1", "label": "Him"}, {"id": "o2", "label": "His"}, {"id": "o3", "label": "He"}]}, {"before": "Would you like", "after": "ice cream?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}, {"id": "o3", "label": "a few"}]}, {"before": "There", "after": "any bananas.", "options": [{"id": "o1", "label": "isn't"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "aren't"}]}, {"before": "I", "after": "work on Sundays. The office is not open.", "options": [{"id": "o1", "label": "never"}, {"id": "o2", "label": "sometimes"}, {"id": "o3", "label": "always"}]}, {"before": "Mark is older", "after": "his brother.", "options": [{"id": "o1", "label": "of"}, {"id": "o2", "label": "than"}, {"id": "o3", "label": "from"}]}, {"before": "He loves", "after": "golf in the summer.", "options": [{"id": "o1", "label": "play"}, {"id": "o2", "label": "to playing"}, {"id": "o3", "label": "playing"}]}, {"before": "It's sunny outside. You", "after": "take an umbrella with you.", "options": [{"id": "o1", "label": "mustn't"}, {"id": "o2", "label": "don't have to"}, {"id": "o3", "label": "can't"}]}, {"before": "The piano is", "after": "the window.", "options": [{"id": "o1", "label": "between"}, {"id": "o2", "label": "in front of"}, {"id": "o3", "label": "behind"}]}, {"before": "My sister's birthday is", "after": "10th February.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "in"}, {"id": "o3", "label": "at"}]}, {"before": "It's", "after": "sunny today. It looks like it is going to rain.", "options": [{"id": "o1", "label": "extremely"}, {"id": "o2", "label": "not very"}, {"id": "o3", "label": "quite"}]}, {"before": "How", "after": "sugar do you want?", "options": [{"id": "o1", "label": "many"}, {"id": "o2", "label": "much"}, {"id": "o3", "label": "long"}]}, {"before": "Can I have", "after": "slice of pizza, please?", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}, {"id": "o3", "label": "any"}]}, {"before": "", "after": "like green tea?", "options": [{"id": "o1", "label": "Will you"}, {"id": "o2", "label": "Are you going to"}, {"id": "o3", "label": "Do you"}]}, {"before": "You", "after": "ride a bike without a helmet.", "options": [{"id": "o1", "label": "mustn't"}, {"id": "o2", "label": "must"}, {"id": "o3", "label": "don't have to"}]}]}$j$::jsonb,10);
