INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('75f7f56e-53dd-5998-bb89-1fe9b5acf0e1','3da71fb6-8264-5338-915a-bd320272cb0c','Revision: Past Simple & General',0,'LESSON',70,$j$[{"type": "text", "text": "This section reviews the grammar of Spark 1: the Past Simple (regular and irregular verbs), there was/were, articles, quantifiers, comparatives, modal verbs and question words."}, {"type": "examples", "items": ["There were many people at the party.", "A cat is bigger than a mouse.", "Where does Jack live? In London."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2fb7b63f-5be9-53bd-b6f9-9d56b627e754','75f7f56e-53dd-5998-bb89-1fe9b5acf0e1',0,'FILL_BLANK','Заполните пропуски глаголами из рамки в Past Simple: come, go, begin, become, can, spend, perform, write.',$j${"items": [{"before": "His mother (come)", "after": "from a wealthy family."}, {"before": "Shakespeare (go)", "after": "to the local Grammar School."}, {"before": "He (begin)", "after": "his career in the theatre as an actor."}, {"before": "He (become)", "after": "famous for writing plays."}, {"before": "Shakespeare (can)", "after": "also write poetry."}, {"before": "He (spend)", "after": "much of his time writing poetry."}, {"before": "They (perform)", "after": "all of Shakespeare's plays."}, {"before": "Shakespeare (write)", "after": "many plays in his lifetime."}]}$j$::jsonb,10);
